import React, { useState } from 'react';
import Aura from '../components/Aura';
import { useMoods, useThoughts } from '../hooks/useStorage';

const GOLD = '#C8A96E';
const MOOD_COLORS = { 1: ['#5C1A1A','#8B2020'], 2: ['#5C2A10','#8B3A15'], 3: ['#3A3010','#6B5515'], 4: ['#0F3A22','#1A6B3A'], 5: ['#0F2A4A','#1A4A8B'] };
const MOOD_EMOJI  = { 1: '😔', 2: '😟', 3: '😐', 4: '🙂', 5: '😄' };
const MOOD_LABEL  = { 1: 'Väldigt dåligt', 2: 'Dåligt', 3: 'Okej', 4: 'Bra', 5: 'Väldigt bra' };
const s = { label: { fontFamily: 'DM Mono, monospace', fontSize: 9, letterSpacing: '0.22em', textTransform: 'uppercase', color: 'rgba(237,233,224,0.3)' } };

export default function History({ setPage }) {
  const { moods, streak, avgMood } = useMoods();
  const { thoughts, trapCounts }   = useThoughts();
  const [expanded, setExpanded]    = useState(null);
  const isEmpty = moods.length === 0 && thoughts.length === 0;
  const maxTrap = Math.max(...Object.values(trapCounts), 1);
  const avgRounded = Math.round(avgMood);

  if (isEmpty) return (
    <div style={{ position: 'relative', height: '100vh', overflow: 'hidden', background: '#080808' }}>
      <Aura colors={['#0F2A4A', '#1A1A4E']} intensity={0.45} />
      <div style={{ position: 'absolute', inset: 0, zIndex: 10, display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', textAlign: 'center', padding: '0 32px' }}>
        <p style={{ ...s.label, marginBottom: 16 }}>Historik · Tom</p>
        <h2 style={{ fontSize: 'clamp(28px,8vw,42px)', fontWeight: 800, letterSpacing: '-0.04em', color: '#ede9e0', marginBottom: 12 }}>Ingenting här än</h2>
        <p style={{ fontSize: 14, color: 'rgba(237,233,224,0.4)', marginBottom: 36, fontWeight: 400 }}>Börja med en tankeanalys.</p>
        <button onClick={() => setPage('home')} style={{ padding: '13px 28px', borderRadius: 100, background: '#ede9e0', color: '#080808', fontSize: 13, fontWeight: 700, border: 'none' }}>
          Analysera en tanke
        </button>
      </div>
    </div>
  );

  const auraColors = avgRounded > 0 ? MOOD_COLORS[avgRounded] : ['#0F2A4A', '#1A1A4E'];

  return (
    <div style={{ minHeight: '100vh', background: '#080808', paddingBottom: 100, position: 'relative' }}>
      <div style={{ position: 'fixed', inset: 0, zIndex: 0 }}>
        <Aura colors={auraColors} intensity={0.3} />
      </div>

      <div style={{ position: 'relative', zIndex: 10, padding: '36px 22px 0' }}>

        {/* Header */}
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', marginBottom: 36 }}>
          <div>
            <p style={s.label}>Historik</p>
            <h1 style={{ fontSize: 'clamp(28px,8vw,42px)', fontWeight: 800, letterSpacing: '-0.05em', color: '#ede9e0', lineHeight: 1.05, marginTop: 8 }}>
              {thoughts.length} {thoughts.length === 1 ? 'analys' : 'analyser'}
            </h1>
          </div>
          {streak > 0 && (
            <div style={{ background: 'rgba(200,169,110,0.1)', border: `0.5px solid rgba(200,169,110,0.25)`, borderRadius: 100, padding: '8px 14px', marginTop: 4 }}>
              <span style={{ fontSize: 12, color: GOLD, fontWeight: 600, fontFamily: 'DM Mono, monospace' }}>🔥 {streak} dagar</span>
            </div>
          )}
        </div>

        {/* Mood orbs */}
        {moods.length > 0 && (
          <div style={{ marginBottom: 28 }}>
            <p style={{ ...s.label, marginBottom: 14 }}>Senaste dagarna</p>
            <div style={{ display: 'flex', gap: 10, alignItems: 'flex-end', flexWrap: 'wrap' }}>
              {[...moods].reverse().map((m, i) => {
                const size = 30 + (m.score * 5);
                const hue = MOOD_COLORS[m.score][1];
                return (
                  <div key={i} style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 5 }}>
                    <div style={{ width: size, height: size, borderRadius: '50%', background: hue, display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: size * 0.38, boxShadow: `0 0 ${size / 2}px ${hue}66` }}>
                      {MOOD_EMOJI[m.score]}
                    </div>
                    <span style={{ fontFamily: 'DM Mono, monospace', fontSize: 8, color: 'rgba(237,233,224,0.22)' }}>
                      {new Date(m.date).toLocaleDateString('sv-SE', { day: '2-digit', month: '2-digit' })}
                    </span>
                  </div>
                );
              })}
            </div>
          </div>
        )}

        <div style={{ height: '0.5px', background: 'rgba(255,255,255,0.08)', margin: '20px 0' }} />

        {/* Trap freq */}
        {Object.keys(trapCounts).length > 0 && (
          <div style={{ marginBottom: 24 }}>
            <p style={{ ...s.label, marginBottom: 16, color: 'rgba(200,169,110,0.6)' }}>Tankefällor</p>
            {Object.entries(trapCounts).sort((a, b) => b[1] - a[1]).slice(0, 5).map(([label, count]) => (
              <div key={label} style={{ display: 'flex', alignItems: 'center', gap: 12, marginBottom: 12 }}>
                <span style={{ fontSize: 12, color: 'rgba(237,233,224,0.45)', flex: 1, fontWeight: 400 }}>{label}</span>
                <div style={{ width: 72, height: 2, background: 'rgba(255,255,255,0.07)', borderRadius: 1 }}>
                  <div style={{ height: '100%', borderRadius: 1, background: 'rgba(200,169,110,0.6)', width: `${(count / maxTrap) * 100}%` }} />
                </div>
                <span style={{ fontFamily: 'DM Mono, monospace', fontSize: 10, color: 'rgba(200,169,110,0.5)', width: 14, textAlign: 'right' }}>{count}</span>
              </div>
            ))}
          </div>
        )}

        {/* Thought log */}
        {thoughts.length > 0 && (
          <>
            <div style={{ height: '0.5px', background: 'rgba(255,255,255,0.08)', margin: '20px 0' }} />
            <p style={{ ...s.label, marginBottom: 14 }}>Tankelog</p>
            {thoughts.map((th, i) => (
              <div key={th.id} style={{ marginBottom: 4 }}>
                <button onClick={() => setExpanded(expanded === i ? null : i)}
                  style={{ width: '100%', textAlign: 'left', padding: '14px 16px', background: expanded === i ? 'rgba(255,255,255,0.07)' : 'rgba(255,255,255,0.04)', border: '0.5px solid rgba(255,255,255,0.08)', borderRadius: expanded === i ? '16px 16px 0 0' : 16, transition: 'all .2s', cursor: 'pointer', backdropFilter: 'blur(12px)' }}>
                  <div style={{ display: 'flex', alignItems: 'center', gap: 12 }}>
                    <span style={{ fontSize: 18 }}>{th.trap_icon || '◎'}</span>
                    <div style={{ flex: 1, minWidth: 0 }}>
                      <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: 4 }}>
                        <span style={{ fontFamily: 'DM Mono, monospace', fontSize: 9, color: GOLD, textTransform: 'uppercase', letterSpacing: '0.08em' }}>{th.trap_label}</span>
                        <span style={{ fontFamily: 'DM Mono, monospace', fontSize: 9, color: 'rgba(237,233,224,0.22)' }}>{new Date(th.date).toLocaleDateString('sv-SE', { day: '2-digit', month: '2-digit' })}</span>
                      </div>
                      <p style={{ fontSize: 12, color: 'rgba(237,233,224,0.32)', fontStyle: 'italic', margin: 0, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: expanded === i ? 'normal' : 'nowrap' }}>
                        "{th.user_text?.slice(0, 80)}{th.user_text?.length > 80 && expanded !== i ? '...' : ''}"
                      </p>
                    </div>
                    <span style={{ fontSize: 11, color: 'rgba(237,233,224,0.2)', transform: expanded === i ? 'rotate(180deg)' : 'none', transition: 'transform .25s', flexShrink: 0 }}>↓</span>
                  </div>
                  {expanded === i && (
                    <div style={{ marginTop: 14, paddingTop: 14, borderTop: '0.5px solid rgba(255,255,255,0.07)', animation: 'fadeIn 0.2s both' }}>
                      <p style={{ ...s.label, marginBottom: 8, color: 'rgba(200,169,110,0.6)' }}>Omramning</p>
                      <p style={{ fontSize: 13, color: 'rgba(237,233,224,0.65)', lineHeight: 1.8, fontWeight: 400 }}>{th.reframe}</p>
                    </div>
                  )}
                </button>
              </div>
            ))}
          </>
        )}
      </div>
    </div>
  );
}
